import { test, expect } from '@playwright/test';

test.describe('Pagination Controls', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/results');
  });

  test('should load the first page of results by default', async ({ page }) => {
    const results = await page.getByRole('list').locator('li');
    expect(await results.count()).toBe(10); // Assuming 10 results per page
    expect(await page.getByText('Page 1 of')).toBeVisible();
  });

  test('should navigate to the second page and load correct results', async ({ page }) => {
    await page.getByRole('button', { name: 'Next' }).click();
    const results = await page.getByRole('list').locator('li');
    expect(await results.count()).toBe(10); // Assuming 10 results per page
    expect(await page.getByText('Page 2 of')).toBeVisible();
  });
});
